import type { Metadata } from "next";
import { site } from "@/lib/site";

// The share card generated by app/opengraph-image.tsx. Setting `openGraph` on a
// page drops the inherited image, so it is listed explicitly.
const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name} — Electrical, CCTV and Computer & IT Services`,
};

/**
 * Metadata for an inner page. Next.js replaces (does not merge) nested fields
 * such as `openGraph` between layout and page, so each page sets its own
 * share title, description and URL here instead of inheriting the home page's.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  const fullTitle = `${title} | ${site.name}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_KE",
      siteName: site.name,
      title: fullTitle,
      description,
      url: path,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [shareImage],
    },
  };
}
